        {n:"大罗天域",cat:"faction",rg:"北界",x:36,y:40,lv:2,d:5,where:"原天罗大陆北界最强势力，域主曼荼罗，总部为浮空大陆大罗天",c:"《大主宰》大罗天域"},
        {n:"大罗天",cat:"place",rg:"大罗天域",x:36,y:38,lv:3,d:4,where:"大罗天域中枢所在的浮空大陆，内置大罗金池等特殊区域",c:"《大主宰》大罗天域"},
        {n:"大罗天军",cat:"faction",rg:"大罗天域",x:34,y:44,lv:3,d:3,where:"大罗天域最精锐和最强军队，由域主直接掌管",c:"《大主宰》大罗天域"},
        {n:"九幽宫",cat:"faction",rg:"大罗天域",x:42,y:46,lv:3,d:3,where:"大罗天域唯一有一双王坐镇的王级势力，麾下军队为九幽卫",c:"《大主宰》大罗天域"},
        {n:"牧府",cat:"faction",rg:"天罗大陆",x:50,y:28,lv:1,d:5,where:"牧尘与曼荼罗共同创建，继承整座上古天宫的资源底蕴；先统一北界，后扩张至北域并统一天罗大陆",c:"《大主宰》牧府"},
        {n:"上古天宫",cat:"faction",rg:"天罗大陆",x:50,y:60,lv:1,d:5,where:"曾统一天罗大陆的势力，共有五殿各有一殿主，宫主天帝是远古时代撼动天地的存在",c:"《大主宰》上古天宫"},
        {n:"陨落战场",cat:"place",rg:"北界",x:26,y:26,lv:3,d:4,where:"北界禁地，邪族侵略大千古战场之一，当年无数强者在此陨落，留诸多地至尊传承",c:"《大主宰》陨落战场"},
        {n:"龙凤山脉",cat:"region",rg:"北界",x:72,y:28,lv:3,d:3,where:"龙凤天所在的山脉",c:"《大主宰》龙凤天"},
        {n:"龙凤天",cat:"place",rg:"龙凤山脉",x:74,y:26,lv:4,d:4,where:"位于龙凤山脉，远古真龙真凤惊天大战双双陨落而形成，内部遍地天材地宝",c:"《大主宰》龙凤天"},
        {n:"龙凤古城",cat:"place",rg:"龙凤山脉",x:76,y:30,lv:4,d:3,where:"龙凤阁固守之地，不对外拓展疆域，树敌极少",c:"《大主宰》龙凤阁"},
        {n:"龙凤阁",cat:"sect",rg:"北界",x:76,y:32,lv:3,d:2,where:"一流势力，只固守在龙凤古城",c:"《大主宰》龙凤阁"},
        {n:"神阁",cat:"faction",rg:"北界",x:24,y:52,lv:3,d:3,where:"北界底蕴最悠久的顶尖势力，经历五次大狩猎战而不灭，麾下有天龙山、白虎山",c:"《大主宰》神阁"},
        {n:"幽冥宫",cat:"faction",rg:"北界",x:30,y:58,lv:3,d:3,where:"北界老牌顶尖势力，经历四次大狩猎战而不灭，和大罗天域是死对头，后臣服牧府",c:"《大主宰》幽冥宫"},
        {n:"玄天殿",cat:"faction",rg:"北界",x:18,y:44,lv:3,d:3,where:"北界顶尖势力之一",c:"《大主宰》玄天殿"},
        {n:"妖门",cat:"faction",rg:"北界",x:20,y:62,lv:3,d:2,where:"北界顶尖势力之一，牧府成立后并入",c:"《大主宰》妖门"},
        {n:"万圣山",cat:"faction",rg:"北界",x:22,y:68,lv:3,d:2,where:"北界顶尖势力之一，牧府成立后并入",c:"《大主宰》万圣山"},
        {n:"蛇神殿",cat:"faction",rg:"北界",x:26,y:72,lv:3,d:2,where:"北界顶尖势力，门下弟子赤血被萧潇所杀",c:"《大主宰》蛇神殿"},
        {n:"天龙山",cat:"place",rg:"北界",x:20,y:54,lv:4,d:2,where:"神阁麾下势力",c:"《大主宰》神阁"},
        {n:"白虎山",cat:"place",rg:"北界",x:18,y:58,lv:4,d:2,where:"神阁麾下势力",c:"《大主宰》神阁"}
