        { n: "苦竹岛", cat: "place", rg: "大晋", x: 73, y: 76, lv: 3, d: 1, where: "大晋邻海小岛，苦竹老人修炼之地，以万木大阵威震海外", c: "《凡人必备手册·地理篇》" }
