  note: "本世界为云境『世界宪法·通讯形态』框架下的开放创作题材，玩家在创世台自建世界，无固定原著、无 canonical 地点。故本数据不标任何虚构书名，如实标注为『开放题材·通用场景素材库』：提供一套可直接取用的模板化舞台（王国/都城/险地/势力总部/宗门/地理区），覆盖 country/faction/sect/region/place 五类。方位无原著可溯，where 字段逐条写明『按通用地理/叙事逻辑推定』的相对布局理由；坐标为可复用的模板摆位（x 东西 0-100、y 南北 0-100），不代表任何真实或原著地理。出处 c 字段指向项目内真实存在的建世方法论知识库（KB_PRESETS['freeworld'] 各讲义），不编造书名。素材库分为八区：中央王畿、北境雪原、西境海岸、东境森林、南境荒沙、域外群岛、中部荒野、若干通用场景。",
