        { n: "厄土", cat: "region", rg: "上苍之上·时空尽头", x: 20, y: 30, lv: 1, d: 5, where: "诡异族群祖地，位于时空尽头，是所有灾难的源头与最终决战之地", c: "《圣墟》（QQ阅读世界观百科）" },
        { n: "诡异高原（高原祖地·葬海）", cat: "region", rg: "厄土", x: 18, y: 28, lv: 2, d: 5, where: "诡异一族祖地，十大诡异始祖受高原庇护可无限复活；‘那个人’葬于高原葬海中心，骨灰侵蚀高原", c: "《圣墟》《遮天》" },
        { n: "祭海祭坛", cat: "place", rg: "高原", x: 15, y: 25, lv: 3, d: 3, where: "祭海深处的祭坛，诡异始祖举行大祭祭祀那位至强者之处，残念在此再现", c: "《圣墟》" },
        { n: "界海", cat: "region", rg: "上苍之上与九天十地之间", x: 75, y: 60, lv: 1, d: 3, where: "界海尽头尸骸仙帝释放黑暗动乱，石昊曾孤身杀入界海，鏖战黑暗四帝", c: "《完美世界》《圣墟》" },
        { n: "仙域", cat: "region", rg: "上苍之下", x: 80, y: 40, lv: 1, d: 3, where: "石昊平定黑暗动乱后独断万古，隔绝仙域与上苍之上的联系；后被叶凡等重组", c: "《完美世界》《遮天》《圣墟》" },
        { n: "九天十地", cat: "region", rg: "下界之上", x: 70, y: 72, lv: 1, d: 3, where: "石昊出身的下界石村所在的广阔世界，曾遭异域入侵，帝关血战，后被独断万古与上苍隔绝", c: "《完美世界》《圣墟》" },
        { n: "异域", cat: "region", rg: "九天十地之外", x: 85, y: 75, lv: 1, d: 3, where: "《完美世界》中入侵九天十地的异域；《圣墟》中亦有异域道统遗迹（如地球奥林匹斯山）", c: "《完美世界》《圣墟》" },
        { n: "诡异道祖势力", cat: "faction", rg: "高原", x: 22, y: 32, lv: 2, d: 4, where: "灰袍青年背后的恐怖势力，三位道祖可震慑诸天，意图抹除现有文明", c: "《圣墟》第1627章" },
        { n: "诸天", cat: "region", rg: "诸天万界统称", x: 50, y: 50, lv: 0, d: 2, where: "诸天万界统称，长期遭诡异一族渗透与血祭，终局几近覆灭；轮回狩猎者被称与诸天为敌", c: "《圣墟》" }
