        {n:"鬼邮局四楼",cat:"place",rg:"鬼邮局内",x:50,y:38,lv:4,d:4,where:"送信任务为乘坐灵异公交车停站三站下车的老林古宅，需在凶宅存活七日并送出一封红色信件",c:"《神秘复苏》搜狗百科·张洞古宅/B站时间线"},
        {n:"鬼邮局五楼",cat:"place",rg:"鬼邮局内",x:50,y:37,lv:4,d:3,where:"信使一战之地；孙瑞撕碎黑色信件、众人抵御袭击后继承管理者之位",c:"《神秘复苏》B站时间线/百度百科"},
        {n:"鬼邮局六楼",cat:"place",rg:"鬼邮局内",x:50,y:36,lv:4,d:2,where:"邮局最高层，红色信件可直达上层，关于灵异源头与管理者秘密；张佑红事件后杨间获六楼消息",c:"《神秘复苏》百度百科/剧情梳理"},
        {n:"地狱公寓（大汉市烂尾楼）",cat:"place",rg:"中国·大汉市",x:48,y:36,lv:3,d:4,where:"原'鬼邮局'现世于一栋烂尾楼，没有收到邀请须有高级鬼域才能强行进入；孙瑞继承管理者后改为'地狱公寓'",c:"《神秘复苏》搜狗/夸克百科·公寓"},
        {n:"黄岗村",cat:"place",rg:"中国·大昌市近郊（推定）",x:54,y:56,lv:3,d:5,where:"一个无缘无故失踪已久的小村庄，村民再次出现时全变成鬼差的鬼奴；这里同时也是鬼差的最初诞生之地，冯全为延缓复苏栖身鬼棺",c:"《神秘复苏》起点中文网百科·地点/百度百科"},
        {n:"鬼棺（黄岗村）",cat:"place",rg:"中国·黄岗村",x:54,y:57,lv:4,d:4,where:"黄岗村内可孕育厉鬼的棺材，鬼差由其诞生；王小明曾利用鬼棺做实验试图改造驭鬼者卫景，实验失败鬼差破棺逃出",c:"《神秘复苏》盘点28副本（微信公号）/起点百科"},
        {n:"训练基地（鬼差事件）",cat:"place",rg:"中国·北方（推定）",x:46,y:32,lv:3,d:4,where:"源于黄岗村遗留鬼棺，王小明在此做改造实验失败致鬼差破棺逃出；鬼差'落单必死'，杨间靠人皮纸、鬼报纸极限周旋",c:"《神秘复苏》盘点28副本（微信公号）/今日头条解析"},
        {n:"大昌市饿死鬼事件现场",cat:"region",rg:"中国·大昌市",x:58,y:50,lv:2,d:5,where:"S级毁灭级事件，饿死鬼（鬼婴四阶段）吞噬整座城市；杨间借鬼镜重生逆转战局，黄金棺材钉封印饿死鬼",c:"《神秘复苏》百度百科·杨间/今日头条解析"},
        {n:"鬼镜",cat:"place",rg:"中国·大昌市（民国古宅/工地）",x:60,y:51,lv:4,d:4,where:"民国时期用来关押收容厉鬼的容器，可记录并复活血肉—需在镜中身影成型时状态重生且外面有人接应，代价是放出镜中一只鬼",c:"《神秘复苏》百度百科·杨间物品（第192章）"},
        {n:"鬼橱",cat:"place",rg:"中国·大昌市（民国古宅第二间房）",x:60,y:51,lv:4,d:4,where:"位于古宅第二间房的老旧橱柜，满足愿望前需完成两个任务，'你将得到一切，也将失去一切'；后被许愿鬼掌握",c:"《神秘复苏》搜狗百科/百度百科·杨间物品"},
        {n:"金门（灵异与现实交界）",cat:"place",rg:"中国·大昌市（民国古宅第三扇门）",x:60,y:51,lv:4,d:4,where:"民国古宅三扇门中的金门，封锁灵异与现实的交界入口；灵异由此入侵现实，人类亦可经此前往灵异世界",c:"《神秘复苏》搜狗百科·第一扇金门后的秘密"},
        {n:"鬼公交（灵异公交车）",cat:"place",rg:"跨时代·跨地点（灵异载具）",x:55,y:48,lv:2,d:5,where:"一辆穿行不同时代、不同地点的公交车，可打开现实与灵异之地界限、压制车内厉鬼，撞击使S级厉鬼死机；秦老自称曾任司机，杨间驾驭一半灵异",c:"《神秘复苏》百度百科·鬼公交/搜狗百科"},
        {n:"鬼出租（灵异出租车）",cat:"place",rg:"中国·大昌市",x:59,y:50,lv:3,d:2,where:"鬼童持有的灵异载具，驾驶出租车撞击可对厉鬼造成压制；杨间后来交给冯全",c:"《神秘复苏》夸克百科·鬼童/B站时间线"},
        {n:"凯撒大酒店",cat:"place",rg:"中国·中山市",x:62,y:72,lv:3,d:5,where:"中山市灵异酒店，有一具高大男尸在楼层飘荡（民国顶尖驭鬼者李庆之）；内镇墓碑与炉火，诅咒生成者须在酒店内刷怪掌握足够强灵异方可安全离开",c:"《神秘复苏》搜狗/夸克百科·凯撒大酒店"},
        {n:"平安大厦",cat:"place",rg:"中国（朋友圈总部）",x:62,y:70,lv:3,d:4,where:"原为朋友圈总部，杨间攻击朋友圈时削掉上面几层；秦老将鬼画与鬼差限制其中，鬼画后被张羡光劫走",c:"《神秘复苏》搜狗/夸克百科·平安大厦"},
        {n:"福寿园",cat:"place",rg:"中国·大海市",x:70,y:78,lv:3,d:4,where:"位于大海市的一座墓园，埋葬数不清的厉鬼，内有守尸人（现已失效）；第二根棺材钉在此获得，规律为在墓碑刻人名杀人",c:"《神秘复苏》搜狗/夸克百科·福寿园/B站全本资料"},
        {n:"太平古镇",cat:"place",rg:"中国·大原市（新镇）/鬼湖（旧镇）",x:36,y:48,lv:3,d:4,where:"旧镇淹没于鬼湖，新镇由何银儿建于大原市；街有脸摊、裁缝铺、纸扎铺、棺材铺，红棺埋驭鬼者、黑棺埋鬼",c:"《神秘复苏》夸克百科·太平古镇"},
        {n:"白水镇",cat:"place",rg:"现实与灵异交织之地（推定南方）",x:66,y:60,lv:3,d:5,where:"一处现实与灵异交织之地，被张羡光称为'诡城'；街上游荡大量亡灵和灵异房屋，一条马路可现亡者魂魄牵手短暂拉出，深处有诡材小楼可拖人入幻境",c:"《神秘复苏》搜狗/夸克百科·白水镇"},
        {n:"张洞古宅（老林中古宅）",cat:"place",rg:"灵异之地（邮局四楼任务）",x:52,y:42,lv:4,d:5,where:"邮局四楼任务，乘灵异公交车停站三站下车到达；一支民国时期团队据点、张洞长眠之地，被老林包围，需按丧葬流程存活七日（入殓守夜报丧吊唁出殡送信）",c:"《神秘复苏》搜狗百科·张洞古宅/盘点28副本"},
        {n:"王家祖宅（大东市古宅）",cat:"place",rg:"中国·大东市",x:82,y:50,lv:4,d:4,where:"王家祖宅，里面有个可以打乱一片区域时间的摆钟，王家将许多鬼关押其中；要拿钟须不断重启自身来到正确时间，古宅曾沉入鬼湖，摆钟后放回",c:"《神秘复苏》搜狗/夸克百科·大东市古宅/摆钟"},
        {n:"鬼湖",cat:"region",rg:"中国·中部（推定）",x:50,y:60,lv:2,d:5,where:"S级毁灭级事件；湖水互通可无视距离前往其它被侵蚀水域，压制沉入的厉鬼，湖底有唐代沉船与刻'地狱已空'青铜门；杨间窃取四成灵异",c:"《神秘复苏》夸克百科·鬼湖/今日头条·鬼湖沉船（第1023章）"},
        {n:"明月小区（大川市）",cat:"place",rg:"中国·大川市",x:30,y:60,lv:3,d:4,where:"大川市明月小区，9栋301室为邮局三楼送错地址；整个小区被'鬼影头'侵蚀，杨间在此关押鬼影头",c:"《神秘复苏》B站时间线/夸克百科·301室"},
        {n:"301室（明月小区9栋）",cat:"place",rg:"中国·大川市·明月小区",x:30,y:60,lv:4,d:4,where:"民国孟小董去世的住房，邮局黄色信件送错地址；内有诡异人偶娃娃媒介，杨间在此补全无头鬼影拼图成为异类",c:"《神秘复苏》夸克百科·301室/百度百科·杨间"},
        {n:"猛鬼区（猛鬼路）",cat:"region",rg:"中国·大川市一带",x:32,y:58,lv:2,d:3,where:"大川市凶地，含明月小区301；A级灾难级'猛鬼路/猛诡路'事件已解决",c:"《神秘复苏》B站全本资料/盘点28副本"},
        {n:"幽灵船",cat:"place",rg:"西方灵异·袭大海市",x:72,y:80,lv:2,d:4,where:"西方灵异入侵载体，袭击大海市；船长室罗盘锁定杨间，引发东西方驭鬼者大战；杨间驾鬼公交撞停后公交损毁、船长战败",c:"《神秘复苏》搜狗/夸克百科·幽灵船事件"},
        {n:"鬼画事件（大京市）",cat:"region",rg:"中国·大京市",x:44,y:18,lv:2,d:5,where:"S级毁灭级，鬼域覆盖大京市，鬼新娘追杀所有目击者；杀人规律为'回忆'，蒙眼是生路，秦老将鬼画封锁于平安大厦",c:"《神秘复苏》今日头条解析/百度百科·鬼画"},
        {n:"鬼梦事件（杨间老家村庄）",cat:"place",rg:"中国·大昌市周边乡村（推定）",x:58,y:46,lv:3,d:3,where:"杨间带江艳返乡过年，表妹梁圆行为诡异、村子暗藏灵异（灵车、鬼梦）；父亲遗留三处地点埋分割尸体，杨间拼接尸体终结鬼梦危机",c:"《神秘复苏》B站时间线/百度百科·鬼梦"},
        {n:"阴阳路",cat:"place",rg:"灵异之地（位置未明）",x:66,y:44,lv:2,d:3,where:"杨间后期封锁阴阳路事件之地；原著未明确具体方位，按灵异地图相对关系推定",c:"《神秘复苏》盘点28副本·杨间封锁阴阳路事件"},
        {n:"黑色雨伞（六层鬼域）",cat:"region",rg:"灵异之地（位置未明）",x:40,y:62,lv:2,d:4,where:"A级灾难级，共六层鬼域，每层找到真正黑伞打开入下一层；雨水冲刷灵异，淋久被同化，第六层有去无回；林蕴徽告知处理方法",c:"《神秘复苏》B站全本资料/夸克百科·雨伞"},
        {n:"大东市饿死鬼事件现场",cat:"region",rg:"中国·大东市",x:82,y:50,lv:2,d:3,where:"大东市爆发的饿死鬼（鬼婴系）事件现场",c:"《神秘复苏》盘点28副本·大东市饿死鬼事件"},
        {n:"桃花源（桃源乡计划）",cat:"place",rg:"鬼画所造灵异幻境",x:46,y:64,lv:3,d:3,where:"张羡光（邮局第二任管理者、张洞之子）筹划'桃源乡计划'，试图以鬼画创造无灵异世界；杨间在阻止该行动中诡眼受压制",c:"《神秘复苏》百度百科·杨间/夸克百科·张羡光"},
        {n:"许愿鬼事件现场",cat:"place",rg:"灵异之地（位置未明）",x:44,y:58,lv:3,d:3,where:"许愿鬼相关事件；其本体被鬼橱/杨间长枪枪杆所用，许愿越大反噬越大，杨间靠重启豁免侵蚀",c:"《神秘复苏》盘点28副本·许愿鬼事件/百度百科·长枪"},
        {n:"国战事件战场",cat:"region",rg:"跨国·大海市及境外",x:70,y:84,lv:2,d:3,where:"国王组织与总部全面开战，幽灵船袭击、多名队长凋零；王小明布局牺牲为人类争取未来",c:"《神秘复苏》盘点28副本·国战事件/夸克百科"},
        {n:"米国幽灵教堂",cat:"place",rg:"北美洲·米国",x:14,y:42,lv:3,d:2,where:"米国的C级限制级灵异事件地（教堂），反映灵异全球化",c:"《神秘复苏》借QQ阅读百科·米国幽灵教堂/夸克百科·危害等级"},
        {n:"恐怖博物馆",cat:"place",rg:"灵异之地（位置未明）",x:38,y:68,lv:3,d:2,where:"A级灾难级灵异事件地'恐怖博物馆'，已解决",c:"《神秘复苏》B站全本资料/夸克百科·危害等级"},
        {n:"天黑有鬼事件地",cat:"region",rg:"灵异之地（位置未明）",x:42,y:72,lv:2,d:2,where:"A级灾难级灵异事件'天黑有鬼'发生地",c:"《神秘复苏》B站全本资料/夸克百科·危害等级"},
        {n:"人头气球事件现场",cat:"region",rg:"中国·大川市",x:30,y:62,lv:2,d:3,where:"A级灾难级事件，人头气球+死人头，发生在大川市",c:"《神秘复苏》盘点28副本·大川市人头气球事件/B站全本资料"},
        {n:"血池事件现场（大昌市郊区）",cat:"region",rg:"中国·大昌市·郊区",x:54,y:53,lv:3,d:2,where:"大昌市郊区爆发的'血池'灵异事件地",c:"《神秘复苏》newton/夸克百科·大昌市"},
        {n:"雨伞事件现场（大昌市郊区）",cat:"region",rg:"中国·大昌市·郊区",x:56,y:56,lv:3,d:2,where:"大昌市郊区爆发的'雨伞'（黑色雨伞）灵异事件地",c:"《神秘复苏》newton/夸克百科·大昌市"},
        {n:"旅馆（S级灵异事件）",cat:"place",rg:"灵异之地（位置未明）",x:48,y:70,lv:3,d:2,where:"S级毁灭级灵异事件，代号'旅馆'；原著未明确具体方位，按灵异地图相对关系推定",c:"《神秘复苏》夸克百科·危害等级（S级）"},
        {n:"寺庙（S级灵异事件）",cat:"place",rg:"灵异之地（位置未明）",x:46,y:66,lv:3,d:2,where:"S级毁灭级灵异事件，代号'寺庙'；可能与弘法寺镇压厉鬼相关，方位按相对关系推定",c:"《神秘复苏》夸克百科·危害等级（S级）/起点百科·弘法寺"},
        {n:"杨戬封印金身（十八层地狱）",cat:"place",rg:"灵异与现实交界（位置未明）",x:58,y:42,lv:2,d:3,where:"杨间与鬼童融合后为防失控自封金身，在张羡光协助下以鬼域创造维持六十年的十八层地狱封锁灵异入侵源头；六十年后金身破、显化为杨戬",c:"《神秘复苏》百度百科·杨间（结局）/quark百科"}
